    if (lineCount === 1) {
        const parts = line.trim().split(/\s+/);
        const m = parseInt(parts[0], 10);
        const b = parseInt(parts[1], 10);
        solve(m, b);
        rl.close();
    }
});

function solve(m, b) {
    // The line is y = -m*x + b, or m*x + y = b
    // We need to find a rectangle [0, x2] x [0, y2] such that all points (x, y) in the rectangle satisfy m*x + y <= b
    // Since the rectangle is axis-aligned and starts from origin (because we can choose any rectangle with all points on or under the line, and trees are at non-negative integer coordinates),
    // the optimal rectangle will have its top-right corner at some point (x2, y2) where y2 = b - m*x2 (if we want to maximize, we'd push to the boundary)
    // But actually, the rectangle must have all its points on or under the line. So for any point (x, y) in the rectangle, m*x + y <= b.
    // The rectangle is [0, x2] x [0, y2]. The most restrictive point is (x2, y2), so we need m*x2 + y2 <= b.
    // To maximize bananas, we want to maximize the sum of (x + y) for all integer points (x, y) with 0 <= x <= x2, 0 <= y <= y2.
    // Sum = sum_{x=0}^{x2} sum_{y=0}^{y2} (x + y)
    //     = sum_{x=0}^{x2} (y2 * x + y2*(y2+1)/2)
    //     = y2 * (x2*(x2+1)/2) + (x2+1) * y2*(y2+1)/2
    //     = y2 * x2*(x2+1)/2 + (x2+1) * y2*(y2+1)/2
    //     = (x2+1) * y2 * (x2 + y2 + 1) / 2

    // We need to maximize this over integer x2 >= 0, y2 >= 0 such that m*x2 + y2 <= b.
    // For a given x2, the maximum y2 is floor((b - m*x2) / 1) = b - m*x2, but we also need y2 >= 0, so x2 <= b/m.
    // Actually, y2 can be at most b - m*x2, but it must be non-negative. So for each valid x2 (0 <= x2 <= floor(b/m)), y2 = b - m*x2.
    // But wait, could a smaller y2 give a better result? No, because increasing y2 increases the sum. So for each x2, we should take the maximum possible y2, which is b - m*x2.
    // However, we need to make sure that the entire rectangle [0, x2] x [0, y2] is on or under the line. The top-right corner (x2, y2) is the critical point. If m*x2 + y2 <= b, then all other points in the rectangle also satisfy the condition since m*x + y <= m*x2 + y2 <= b for x <= x2 and y <= y2.

    // So we iterate x2 from 0 to floor(b/m), compute y2 = b - m*x2, and calculate the total bananas.

    let maxBananas = 0n;
    const maxX2 = Math.floor(b / m);

    for (let x2 = 0; x2 <= maxX2; x2++) {
        const y2 = b - m * x2;
        if (y2 < 0) break;

        // Sum = (x2+1) * y2 * (x2 + y2 + 1) / 2
        // Use BigInt to avoid overflow
        const term1 = BigInt(x2 + 1);
        const term2 = BigInt(y2);
        const term3 = BigInt(x2 + y2 + 1);
        const product = term1 * term2 * term3;
        const total = product / 2n;

        if (total > maxBananas) {
            maxBananas = total;
        }
    }

    console.log(maxBananas.toString());
}
